const LANDMARK_POOL = [EiffelParisSvg, FourviereLyonSvg, NotreDameGardeMarseilleSvg] as const;

export function DestinationLandmarkDecoration({
  variant,
}: {
  variant: DestinationVariant;
}) {
  // Tirage côté client uniquement (après montage) pour éviter tout
  // mismatch d'hydratation SSR/CSR : le serveur ne peut pas deviner
  // quel monument le client affichera.
  const [Landmark, setLandmark] = useState<(typeof LANDMARK_POOL)[number] | null>(null);

  useEffect(() => {
    setLandmark(LANDMARK_POOL[Math.floor(Math.random() * LANDMARK_POOL.length)]);
  }, []);

  if (!Landmark) return null;

  return (
    <div
      aria-hidden="true"
      className={cn(
        "pointer-events-none absolute top-16 right-0 z-0 hidden select-none lg:block",
        VARIANT_COLOR_CLASS[variant]
      )}
      style={{ width: "clamp(200px, 22vw, 380px)" }}
    >
      <Landmark className="h-auto w-full" />
    </div>
  );
}
